typedef unsigned int entity_flavor_t;

extern "C" unsigned int strlen(const char *);

class stringx {
    void *data;
    int reserved;
public:
    stringx();
    stringx(const char *, int = -1);
    stringx(const stringx &);
    ~stringx(int = 2);
    stringx &operator=(const stringx &);
    void make_room(int);
    void append(const stringx &);
    void append(const char *, int);
    int length() const;
};

inline stringx operator+(const stringx &left, const char *right)
{
    stringx result;
    int right_length = strlen(right);
    result.make_room(left.length() + right_length);
    result.append(left);
    result.append(right, right_length);
    return result;
}

struct entity_id {
    unsigned int value;
};

class entity {
    char data[0x208];
public:
    entity(const entity_id &, entity_flavor_t, unsigned int);
    virtual ~entity();
};

class file_finder {
public:
    stringx find_file(const stringx &, const stringx &, bool) const;
};

extern file_finder *g_file_finder;

class os_developer_options {
    int unused;
    int flags;
public:
    enum developer_option_t {
        FLAG_STASH_ONLY
    };

    static os_developer_options *inst();
    bool is_flagged(developer_option_t) const { return flags; }
};

extern os_developer_options *os_developer_options_instance;

inline os_developer_options *os_developer_options::inst()
{
    return os_developer_options_instance;
}

class particle {
    char data[56];
};

struct zero_vector {
    int x;
    int y;
    int z;
    zero_vector() : x(0), y(0), z(0) {}
};

class particle_generator : public entity {
    stringx filename;
    particle *particles;
    char padding[0x78];
    int max_particles;
    char padding2[0x70];
    zero_vector forces;
public:
    particle_generator(const stringx &, const entity_id &, entity_flavor_t,
                       unsigned int);
    virtual ~particle_generator();
    void initialize_variables();
    void load();
};

particle_generator::particle_generator(const stringx &_filename,
                                       const entity_id &_id,
                                       entity_flavor_t _flavor,
                                       unsigned int _flags)
    : entity(_id, _flavor, _flags)
{
    if (!os_developer_options::inst()->is_flagged(
            os_developer_options::FLAG_STASH_ONLY))
        filename = g_file_finder->find_file(_filename, ".ent", false);
    else
        filename = _filename + ".ent";

    initialize_variables();
    load();

    if (particles == 0) {
        particles = new particle[max_particles];
    }
}
